{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Push for a smaller de minimis and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general-warranty period and longer, legally appropriate periods for tax and other latent risks."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental warranties—especially authority, ownership and title to the shares—should not be subject to the general cap or 18-month period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "carve out fraud and other non-excludable liability"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require specific, fair disclosure against the relevant warranty, with enough detail for the Buyer to identify the nature and scope of the issue."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject a bar based on anything the Buyer or advisers “had knowledge” of or could find through searches."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require the condition to be satisfied only when valid, unconditional consent is obtained and all associated conditions are met"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment at or before Completion from the completion funds flow, with lender payout evidence, executed releases and an effective discharge of security"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "typically as a Seller-funded or price-adjusting completion liability, including applicable on-costs, rather than an undisclosed post-completion burden on the Buyer"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require verified payment and an effective assignment/confirmation of all relevant IP before Completion, or a specific, adequately capped indemnity with escrow/retention"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require continued investigation and delivery of findings and remediation evidence before Completion"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Require the underlying contracts, renewal dates, termination rights and accrued/committed amounts."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "avoid applying a general limitation to every type of Claim by default"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Do not accept the register alone as a substitute for those protections."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek stronger caps and thresholds, appropriately longer and differentiated claim periods, and clear carve-outs for fundamental warranties, tax, specific indemnities and fraud."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

